export async function POST() {
  try {
    console.log('--- Iniciando Sincronizacion Real ---')

    // 1. Limpiar datos existentes
    await prisma.historialVerificacion.deleteMany()
    await prisma.instrumentoEquipo.deleteMany()

    // 2. Insertar Equipos
    console.log(`Insertando ${EQUIPOS_SEED.length} equipos...`)
    for (const equipo of EQUIPOS_SEED) {
      await prisma.instrumentoEquipo.create({ data: equipo as any })
    }

    // 3. Insertar Instrumentos
    console.log(`Insertando ${INSTRUMENTOS_SEED.length} instrumentos...`)
    for (const instrumento of INSTRUMENTOS_SEED) {
      await prisma.instrumentoEquipo.create({ data: instrumento as any })
    }

    // 4. Insertar Historial (Solo los que tienen FK valida)
    const validEquipos = [...EQUIPOS_SEED, ...INSTRUMENTOS_SEED].map(e => e.ID_Equipo)
    const validHistorial = HISTORIAL_SEED.filter(h => validEquipos.includes(h.FK_ID_Equipo))

    console.log(`Insertando ${validHistorial.length} registros de historial...`)
    for (const h of validHistorial) {
      await prisma.historialVerificacion.create({ data: h })
    }

    return NextResponse.json({ 
      success: true, 
      message: 'Sincronizacion completa con Historial Real Purificado',
      stats: {
        equipos: EQUIPOS_SEED.length,
        instrumentos: INSTRUMENTOS_SEED.length,
        historial: validHistorial.length
      }
    })
  } catch (error) {
    console.error('Error en seed:', error)
    return NextResponse.json({ success: false, error: String(error) }, { status: 500 })
  }
}
